public Options addOptions(final Options options) {
    if (options == null) {
        throw new IllegalArgumentException("Options cannot be null");
    }

    // Check for duplicate short options
    for (Option option : options.shortOpts.values()) {
        if (shortOpts.containsKey(option.getKey())) {
            throw new IllegalArgumentException("Duplicate short option: " + option.getKey());
        }
    }

    // Check for duplicate long options
    for (Option option : options.longOpts.values()) {
        if (longOpts.containsKey(option.getLongOpt())) {
            throw new IllegalArgumentException("Duplicate long option: " + option.getLongOpt());
        }
    }

    // Add options
    for (Option option : options.shortOpts.values()) {
        addOption(option);
    }

    // Add option groups
    for (Map.Entry<String, OptionGroup> entry : options.optionGroups.entrySet()) {
        addOptionGroup(entry.getValue());
    }

    return this;
}
