protected List<Queue<String>> makeColumnQueues(final List<String> columnData, final List<TextStyle> styles) {
    if (columnData == null || styles == null) {
        throw new IllegalArgumentException("columnData and styles must not be null");
    }
    if (columnData.size() != styles.size()) {
        throw new IndexOutOfBoundsException("styles list must match the size of columnData list");
