public CharSequence pad(final boolean addIndent, final CharSequence text) {
    if (text == null) {
        throw new IllegalArgumentException("Text cannot be null");
    }

    int maxWidth = this.maxWidth;
    int textLength = text.length();

    // If text is longer than or equal to maxWidth, return it unchanged
    if (textLength >= maxWidth) {
        return text;
    }

    // Calculate total padding needed
    int totalPadding = maxWidth - textLength;
    StringBuilder paddedText = new StringBuilder();

    // Add left padding
    for (int i = 0; i < leftPad; i++) {
        paddedText.append(' ');
    }

    // Add indentation if required
    if (addIndent) {
        for (int i = 0; i < indent; i++) {
            paddedText.append(' ');
        }
    }

    // Calculate padding based on alignment
    int leftPadding = 0;
    int rightPadding = 0;

    switch (alignment) {
        case LEFT:
            // No extra padding needed for left alignment
            break;
        case CENTER:
            leftPadding = totalPadding / 2;
            rightPadding = totalPadding - leftPadding;
            break;
        case RIGHT:
            rightPadding = totalPadding;
            break;
    }

    // Add left padding for center/right alignment
    for (int i = 0; i < leftPadding; i++) {
        paddedText.append(' ');
    }

    // Append the original text
    paddedText.append(text);

    // Add right padding for right alignment
    for (int i = 0; i < rightPadding; i++) {
        paddedText.append(' ');
    }

    return paddedText.toString();
}
